-- Seed inventory data: one inventory_items row + one matching
-- inventory_audit_log 'CREATED' row for every SKU in product-service's
-- catalog (10 handwritten V1 SKUs + 5,000 bulk-generated V2 SKUs).
-- SKU codes are extracted verbatim from product-service's own migrations
-- so the two services' catalogs can never drift apart.
-- Quantities are deterministically randomized (random.seed(42) in the
-- generator script) so every fresh environment gets identical data:
-- mostly 1-500, with ~5% forced to 0 to simulate out-of-stock items.
-- reorder_threshold is left out of the column list so the table DEFAULT
-- (10) applies to every seeded row.
-- Total rows: 5010 inventory_items + 5010 inventory_audit_log

